// Helpers for list views.
export function truncate(text, max) {
  if (text.length <= max) return text;
  if (max <= 0) return '';
  const ellipsis = '...';
  if (max <= ellipsis.length) return ellipsis.slice(0, max);
  return text.slice(0, max - ellipsis.length) + ellipsis;
}

export function capitalize(text) {
  return text.charAt(0).toUpperCase() + text.slice(1);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { truncate, capitalize } from '../src/text.js';

test('short text is left alone', () => assert.equal(truncate('hi', 5), 'hi'));
test('capitalize raises the first letter', () => assert.equal(capitalize('ab'), 'Ab'));

test('cut text ends in an ellipsis', () => {
  assert.equal(truncate('hello world', 8), 'hello...');
});

test('cut text never exceeds max', () => {
  for (const max of [0, 1, 2, 3, 4, 5, 8, 20]) {
    const result = truncate('hello world, this is a long sentence', max);
    assert.ok(result.length <= max, `length ${result.length} exceeds max ${max}`);
  }
});

test('text of exactly max length is unchanged', () => {
  assert.equal(truncate('hello', 5), 'hello');
});

test('very small max still respects the limit', () => {
  assert.equal(truncate('hello', 0), '');
  assert.equal(truncate('hello', 2), '..');
  assert.equal(truncate('hello', 3), '...');
});

